// Inline base64 copies of the watermark logo and signature seal used by
// Employee salary documents and the Training report PDF.
//
// Deliberately NOT read from disk at runtime: apps/api deploys to Vercel as
// a single serverless function bundled via @vercel/node (see apps/api/api/
// index.ts), which uses its own file-tracing/bundling pipeline -- entirely
// different from the local `nest build` (tsc) output this was previously
// tested against. A __dirname-relative path to a static asset that works in
// one build pipeline silently breaks in the other (confirmed: the watermark
// rendered locally but was missing from the live-generated PDF). Embedding
// the bytes directly in a normal TS module sidesteps the whole problem --
// module imports resolve identically under every bundler.

export const CREASPARK_LOGO_BASE64 = "";

export const SEAL_MAIN_BASE64 = "";
